1	//! The [`Session`] trait and its carrier types.
2	//!
3	//! `Session` models conversation persistence as an **append-only event
4	//! log**, not a flat message list. The event-log shape gives evals
5	//! (deterministic replay), durability (Temporal/Restate-style event
6	//! sourcing), and an audit trail for regulated deployments.
7	
8	use async_trait::async_trait;
9	use jiff::Timestamp;
10	use serde::{Deserialize, Serialize};
11	
12	use crate::{AgentEvent, ContentPart, Item};
13	
14	/// Conversation persistence as an append-only event log.
15	///
16	/// See the *Sessions* concept page for the rationale.
17	///
18	/// # Example
19	///
20	/// ```
21	/// use async_trait::async_trait;
22	/// use paigasus_helikon_core::{
23	///     ConversationSnapshot, SequenceId, Session, SessionError, SessionEvent,
24	/// };
25	///
26	/// struct MemorySession;
27	///
28	/// #[async_trait]
29	/// impl Session for MemorySession {
30	///     async fn append(
31	///         &self,
32	///         _events: &[SessionEvent],
33	///     ) -> Result<(), SessionError> {
34	///         Ok(())
35	///     }
36	///
37	///     async fn events(
38	///         &self,
39	///         _since: Option<SequenceId>,
40	///     ) -> Result<Vec<SessionEvent>, SessionError> {
41	///         Ok(Vec::new())
42	///     }
43	///
44	///     async fn snapshot(&self) -> Result<ConversationSnapshot, SessionError> {
45	///         Ok(ConversationSnapshot::default())
46	///     }
47	/// }
48	/// ```
49	#[async_trait]
50	pub trait Session: Send + Sync {
51	    /// Append events to the log.
52	    async fn append(&self, events: &[SessionEvent]) -> Result<(), SessionError>;
53	
54	    /// Read events from the log, optionally only those after `since`.
55	    async fn events(&self, since: Option<SequenceId>) -> Result<Vec<SessionEvent>, SessionError>;
56	
57	    /// Compute (or read) a [`ConversationSnapshot`] projection of the log.
58	    async fn snapshot(&self) -> Result<ConversationSnapshot, SessionError>;
59	}
60	
61	/// One entry in the conversation event log.
62	///
63	/// `UserMessage` / `AssistantMessage` / `ToolReturned` carry
64	/// `Vec<ContentPart>` directly (not `Item`) because the SessionEvent
65	/// variant *is* the role — wrapping `Item::UserMessage` inside
66	/// `SessionEvent::UserMessage` would double-tag.
67	#[derive(Debug, Clone, Serialize, Deserialize)]
68	#[serde(tag = "type", rename_all = "snake_case")]
69	#[non_exhaustive]
70	pub enum SessionEvent {
71	    /// A user-authored message.
72	    ///
73	    /// The enum is marked `#[non_exhaustive]` at the enum level (not per
74	    /// variant) so downstream tests and fixtures can construct variants
75	    /// by struct-init to pin a deterministic `ts`. Don't tighten this to
76	    /// per-variant `#[non_exhaustive]`.
77	    UserMessage {
78	        /// Content blocks of the message.
79	        content: Vec<ContentPart>,
80	        /// Wall-clock instant the event was recorded. UTC, nanosecond precision.
81	        ts: Timestamp,
82	    },
83	    /// An assistant-authored message attributed to a named agent.
84	    AssistantMessage {
85	        /// Content blocks of the message.
86	        content: Vec<ContentPart>,
87	        /// Name of the emitting [`crate::Agent`]. `String` (not `Option`)
88	        /// because the runner always knows which agent emitted when
89	        /// appending to the log.
90	        agent: String,
91	        /// Wall-clock instant the event was recorded. UTC, nanosecond precision.
92	        ts: Timestamp,
93	    },
94	    /// The runner invoked a tool.
95	    ToolCalled {
96	        /// Provider-assigned call identifier.
97	        call_id: String,
98	        /// Tool name.
99	        name: String,
100	        /// JSON arguments.
101	        args: serde_json::Value,
102	        /// Wall-clock instant the event was recorded. UTC, nanosecond precision.
103	        ts: Timestamp,
104	    },
105	    /// The tool returned.
106	    ToolReturned {
107	        /// Matching call identifier.
108	        call_id: String,
109	        /// Content blocks of the tool's output (Anthropic permits
110	        /// text + image inside a tool result).
111	        content: Vec<ContentPart>,
112	        /// Wall-clock instant the event was recorded. UTC, nanosecond precision.
113	        ts: Timestamp,
114	    },
115	    /// Control transferred from one agent to another.
116	    HandoffOccurred {
117	        /// Outgoing agent name.
118	        from: String,
119	        /// Incoming agent name.
120	        to: String,
121	        /// Wall-clock instant the event was recorded. UTC, nanosecond precision.
122	        ts: Timestamp,
123	    },
124	    /// Older events were compacted into a summary.
125	    ///
126	    /// **Provider-translator caveat:** [`project`] renders this as
127	    /// [`Item::System`]. Both shipped provider translators reshape
128	    /// `Item::System`: Anthropic hoists every system block into the
129	    /// top-level `system` field, and OpenAI concatenates multiple system
130	    /// blocks into one at the top of the conversation. The "summary
131	    /// replaces turns 1..N at this position" semantic is therefore
132	    /// observation-only in the event log; the model sees the summary text
133	    /// but as a top-level system instruction, not a positional cutover.
134	    Compacted {
135	        /// LLM-produced summary.
136	        summary: String,
137	        /// Number of events the summary replaces. `u64` (not `usize`)
138	        /// because the value is serialized into the persisted log — a
139	        /// 32-bit consumer must read what a 64-bit producer wrote.
140	        original_count: u64,
141	        /// Wall-clock instant the event was recorded. UTC, nanosecond precision.
142	        ts: Timestamp,
143	    },
144	}
