508	/// Monotonic position in a [`Session`]'s append-only log.
509	#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash, Serialize, Deserialize)]
510	pub struct SequenceId(pub u64);
511	
512	/// A computed projection of a [`Session`]'s log into a single
513	/// conversation state. The `messages` field is the canonical view a
514	/// session emits.
515	#[derive(Debug, Clone, Default, Serialize, Deserialize)]
516	#[non_exhaustive]
517	pub struct ConversationSnapshot {
518	    /// Canonical message list, in conversational order.
519	    pub messages: Vec<Item>,
520	}
