522	/// Errors raised by [`Session`] methods.
523	#[derive(Debug, thiserror::Error)]
524	#[non_exhaustive]
525	pub enum SessionError {
526	    /// Backend unreachable (database down, file locked, …).
527	    #[error("session backend unavailable")]
528	    Unavailable,
529	
530	    /// A backend-specific error, type-erased so core stays free of any
531	    /// particular backend dependency. The `'static` bound is required for
532	    /// `<dyn Error>::downcast_ref` to work; callers who care about
533	    /// the underlying type can do `err.downcast_ref::<sqlx::Error>()`.
534	    #[error(transparent)]
535	    Backend(Box<dyn std::error::Error + Send + Sync + 'static>),
536	
537	    /// Escape hatch.
538	    #[error(transparent)]
539	    Other(#[from] anyhow::Error),
540	}
541	
542	impl SessionError {
543	    /// Wrap a backend-specific error as [`SessionError::Backend`].
544	    ///
545	    /// Saves the
546	    /// `.map_err(|e| SessionError::Backend(Box::new(e)))` boilerplate at
547	    /// every query call site — use as `.map_err(SessionError::backend)`.
548	    pub fn backend<E>(e: E) -> Self
549	    where
550	        E: std::error::Error + Send + Sync + 'static,
551	    {
552	        Self::Backend(Box::new(e))
553	    }
554	}
