1	//! Covers acceptance criterion #2 from SMA-318 (concurrency): N tasks
2	//! appending to the same `session_id` produce a contiguous sequence with
3	//! no gaps or duplicates.
4	//!
5	//! **Why not loom:** loom models pure-Rust concurrency primitives and
6	//! can't reason about SQLite's lock state machine. Using a real
7	//! `tokio::test` with a file-backed pool exercises the actual write-lock
8	//! path. The 30-second busy timeout absorbs slow CI runners where 160
9	//! sequential `BEGIN IMMEDIATE` transactions can approach the default 5
10	//! seconds.
11	
12	use std::sync::Arc;
13	use std::time::Duration;
14	
15	use jiff::Timestamp;
16	use paigasus_helikon_core::{ContentPart, Session, SessionEvent};
17	use paigasus_helikon_sessions_sqlite::SqliteSession;
18	use sqlx::sqlite::{SqliteConnectOptions, SqliteJournalMode, SqlitePoolOptions};
19	
20	const N_TASKS: usize = 16;
21	const M_EVENTS_PER_TASK: usize = 10;
22	
23	#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
24	async fn concurrent_appends_produce_contiguous_sequence() {
25	    let dir = tempfile::tempdir().expect("tempdir");
26	    let path = dir.path().join("concurrent.db");
27	
28	    let opts = SqliteConnectOptions::new()
29	        .filename(&path)
30	        .create_if_missing(true)
31	        .journal_mode(SqliteJournalMode::Wal)
32	        .busy_timeout(Duration::from_secs(30));
33	    let pool = SqlitePoolOptions::new()
34	        .max_connections(8)
35	        .connect_with(opts)
36	        .await
37	        .expect("pool");
38	    SqliteSession::migrate(&pool).await.expect("migrate");
39	
40	    let session = Arc::new(SqliteSession::open_without_migrate(pool, "shared"));
41	
42	    let handles = (0..N_TASKS)
43	        .map(|task_idx| {
44	            let s = session.clone();
45	            tokio::spawn(async move {
46	                for j in 0..M_EVENTS_PER_TASK {
47	                    let ev = SessionEvent::UserMessage {
48	                        content: vec![ContentPart::Text {
49	                            text: format!("task-{task_idx}-msg-{j}"),
50	                        }],
51	                        ts: Timestamp::from_second(1_700_000_000).unwrap(),
52	                    };
53	                    s.append(&[ev]).await.expect("append");
54	                }
55	            })
56	        })
57	        .collect::<Vec<_>>();
58	
59	    for h in handles {
60	        h.await.expect("task panicked");
61	    }
62	
63	    let all = session.events(None).await.expect("events");
64	    let expected = N_TASKS * M_EVENTS_PER_TASK;
65	    assert_eq!(all.len(), expected, "total event count");
66	
67	    // The sequence column is internal; we observe it indirectly: every
68	    // event we read back must be one of the ones we sent.
69	    let mut texts: Vec<String> = all
70	        .into_iter()
71	        .filter_map(|ev| match ev {
72	            SessionEvent::UserMessage { content, .. } => match content.into_iter().next() {
73	                Some(ContentPart::Text { text }) => Some(text),
74	                _ => None,
75	            },
76	            _ => None,
77	        })
78	        .collect();
79	    texts.sort();
80	
81	    let mut expected_texts: Vec<String> = (0..N_TASKS)
82	        .flat_map(|t| (0..M_EVENTS_PER_TASK).map(move |j| format!("task-{t}-msg-{j}")))
83	        .collect();
84	    expected_texts.sort();
85	
86	    assert_eq!(
87	        texts, expected_texts,
88	        "every sent event is present exactly once"
89	    );
90	}
